// Provided once above MaterialApp, so every screen shares it
class PasswordVisibilityCubit extends Cubit<bool> {
  PasswordVisibilityCubit() : super(false);
  void toggle() => emit(!state);
}

class PasswordField extends StatelessWidget {
  const PasswordField({super.key});

  @override
  Widget build(BuildContext context) {
    final visible = context.watch<PasswordVisibilityCubit>().state;
    return TextField(
      obscureText: !visible,
      decoration: InputDecoration(
        suffixIcon: IconButton(
          icon: Icon(visible ? Icons.visibility_off : Icons.visibility),
          onPressed: context.read<PasswordVisibilityCubit>().toggle,
        ),
      ),
    );
  }
}

class PasswordField extends StatefulWidget {
  const PasswordField({super.key});

  @override
  State<PasswordField> createState() => _PasswordFieldState();
}

class _PasswordFieldState extends State<PasswordField> {
  bool _visible = false; // ephemeral: only this field cares

  @override
  Widget build(BuildContext context) => TextField(
        obscureText: !_visible,
        decoration: InputDecoration(
          suffixIcon: IconButton(
            icon: Icon(_visible ? Icons.visibility_off : Icons.visibility),
            onPressed: () => setState(() => _visible = !_visible),
          ),
        ),
      );
}
